CREATE OR ALTER PROCEDURE [dbo].[uspUomConversion_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @FromUnitId UNIQUEIDENTIFIER = NULL
	, @ToUnitId UNIQUEIDENTIFIER = NULL
	, @EffectiveOn DATE = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ConversionFactor]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[FromUnitId]
			, j1.[Name] AS [FromUnitName]
			, t.[ToUnitId]
			, j2.[Name] AS [ToUnitName]
			, t.[IsActive]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[UomConversion] AS t
		LEFT JOIN [dbo].[UnitMeasure] AS j1 ON j1.[Id] = t.[FromUnitId]
		LEFT JOIN [dbo].[UnitMeasure] AS j2 ON j2.[Id] = t.[ToUnitId]
		WHERE 1 = 1
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@FromUnitId IS NULL OR t.[FromUnitId] = @FromUnitId)
			AND (@ToUnitId IS NULL OR t.[ToUnitId] = @ToUnitId)
			AND (@EffectiveOn IS NULL OR ((t.[EffectiveFrom] IS NULL OR t.[EffectiveFrom] <= @EffectiveOn) AND (t.[EffectiveTo] IS NULL OR t.[EffectiveTo] >= @EffectiveOn)))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'conversionFactor' THEN r.[ConversionFactor] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'conversionFactor' THEN r.[ConversionFactor] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fromUnitId' THEN r.[FromUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fromUnitId' THEN r.[FromUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fromUnitName' THEN r.[FromUnitName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fromUnitName' THEN r.[FromUnitName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'toUnitId' THEN r.[ToUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'toUnitId' THEN r.[ToUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'toUnitName' THEN r.[ToUnitName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'toUnitName' THEN r.[ToUnitName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isActive' THEN r.[IsActive] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isActive' THEN r.[IsActive] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
